package org.example.animalsheltersecurity.model;

import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;

/**
 * Handover act prepared for an adoption application.
 * Dates are always generated by the server.
 */
@Entity
@Table(name = "animal_handover_records")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class AnimalHandoverRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.EAGER, optional = false)
    @JoinColumn(name = "application_id", nullable = false)
    private AdoptionApplication application;

    @Column(nullable = false)
    private LocalDateTime preparationDate;

    private LocalDateTime confirmationDate;

    /**
     * Handover status, for example PREPARED, CONFIRMED, CANCELLED.
     */
    @Column(nullable = false)
    private String status;
}
